"""Legal move generation.

Strategy: generate pseudo-legal moves, then filter by making each move and
rejecting those that leave the mover's king attacked. This is slower than
pin-aware generation but trivially correct, which is the point of perft.
"""

from typing import List

from .board import (
    Board,
    WHITE,
    BLACK,
    Move,
    KNIGHT_DELTAS,
    KING_DELTAS,
    ORTHO_DELTAS,
    DIAG_DELTAS,
    sq_index,
)

PROMO_PIECES = ("q", "r", "b", "n")


def _is_own(piece: str, color: str) -> bool:
    if piece is None:
        return False
    return piece.isupper() if color == WHITE else piece.islower()


def _is_enemy(piece: str, color: str) -> bool:
    if piece is None:
        return False
    return piece.islower() if color == WHITE else piece.isupper()


def _pawn_moves(board: Board, frm: int, moves: List[str]) -> None:
    b = board.squares
    color = board.side
    f, r = frm % 8, frm // 8
    step = 1 if color == WHITE else -1
    start_rank = 1 if color == WHITE else 6
    promo_rank = 7 if color == WHITE else 0

    # Pushes.
    one = sq_index(f, r + step)
    if b[one] is None:
        if r + step == promo_rank:
            for p in PROMO_PIECES:
                moves.append((frm, one, p, Move.NORMAL))
        else:
            moves.append((frm, one, None, Move.NORMAL))
            if r == start_rank:
                two = sq_index(f, r + 2 * step)
                if b[two] is None:
                    moves.append((frm, two, None, Move.DOUBLE_PUSH))

    # Captures (including en passant).
    for df in (-1, 1):
        nf = f + df
        if not (0 <= nf < 8):
            continue
        nr = r + step
        to = sq_index(nf, nr)
        target = b[to]
        if _is_enemy(target, color) or to == board.ep:
            if r + step == promo_rank and to == board.ep is not True:
                pass  # ep can never be a promotion; fall through handled below
            if r + step == promo_rank:
                for p in PROMO_PIECES:
                    moves.append((frm, to, p, Move.NORMAL))
            else:
                flag = Move.EN_PASSANT if (to == board.ep and target is None) else Move.NORMAL
                moves.append((frm, to, None, flag))


def _piece_moves(board: Board, frm: int, deltas, sliding: bool, moves: List[str]) -> None:
    b = board.squares
    color = board.side
    f, r = frm % 8, frm // 8
    for df, dr in deltas:
        nf, nr = f + df, r + dr
        while 0 <= nf < 8 and 0 <= nr < 8:
            to = sq_index(nf, nr)
            p = b[to]
            if p is None:
                moves.append((frm, to, None, Move.NORMAL))
            else:
                if _is_enemy(p, color):
                    moves.append((frm, to, None, Move.NORMAL))
                break
            if not sliding:
                break
            nf += df
            nr += dr


def _castling_moves(board: Board, moves: List[str]) -> None:
    enemy = BLACK if board.side == WHITE else WHITE
    if board.side == WHITE:
        if "K" in board.castling:
            if (
                board.squares[5] is None
                and board.squares[6] is None
                and not any(board.is_attacked(s, enemy) for s in (4, 5, 6))
            ):
                moves.append((4, 6, None, Move.CASTLE))
        if "Q" in board.castling:
            if (
                board.squares[3] is None
                and board.squares[2] is None
                and board.squares[1] is None
                and not any(board.is_attacked(s, enemy) for s in (4, 3, 2))
            ):
                moves.append((4, 2, None, Move.CASTLE))
    else:
        if "k" in board.castling:
            if (
                board.squares[61] is None
                and board.squares[62] is None
                and not any(board.is_attacked(s, enemy) for s in (60, 61, 62))
            ):
                moves.append((60, 62, None, Move.CASTLE))
        if "q" in board.castling:
            if (
                board.squares[59] is None
                and board.squares[58] is None
                and board.squares[57] is None
                and not any(board.is_attacked(s, enemy) for s in (60, 59, 58))
            ):
                moves.append((60, 58, None, Move.CASTLE))


def generate_pseudo_legal(board: Board) -> List[tuple]:
    moves: List[tuple] = []
    b = board.squares
    white = board.side == WHITE
    own_pieces = "PNBRQK" if white else "pnbrqk"

    for frm, piece in enumerate(b):
        if piece is None or piece not in own_pieces:
            continue
        t = piece.upper()
        if t == "P":
            _pawn_moves(board, frm, moves)
        elif t == "N":
            _piece_moves(board, frm, KNIGHT_DELTAS, False, moves)
