import pytest

from chessgen import Board, perft, divide

START_FEN = "rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1"
KIWIPETE_FEN = "r3k2r/p1ppqpb1/bn2pnp1/3PN3/1p2P3/2N2Q1p/PPPBBPPP/R3K2R w KQkq - 0 1"


def test_startpos_perft_2():
    assert perft(Board(START_FEN), 2) == 400


@pytest.mark.parametrize(
    "depth,expected",
    [(1, 48), (2, 2039), (3, 97862)],
)
def test_kiwipete_perft(depth, expected):
    assert perft(Board(KIWIPETE_FEN), depth) == expected


def test_divide_sums_match():
    board = Board(KIWIPETE_FEN)
    parts = divide(board, 2)
    assert sum(parts.values()) == 2039
